  -- H.R. 6644 → housing_build (primary), yea_supports
  VALUES (m_h_r_6644, 'housing_build', 100, true, 'yea_supports', '21st Century ROAD to Housing Act is a housing-supply package — it targets the regulatory and financing barriers to new residential construction; a yea is a vote to build more housing.', 'https://www.congress.gov/bill/119th-congress/house-bill/6644')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 6644 → housing, yea_supports
  VALUES (m_h_r_6644, 'housing', 80, false, 'yea_supports', 'Secondary: the same package also carries affordability and federal housing-assistance provisions, so a yea advances housing affordability generally, not only new supply.', 'https://www.congress.gov/bill/119th-congress/house-bill/6644')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.Con.Res. 108 → restraint (primary), yea_supports
  VALUES (m_h_con_res_108, 'restraint', 100, true, 'yea_supports', 'Tlaib War Powers concurrent resolution directing the President under section 5(c) of the War Powers Resolution to remove United States Armed Forces from hostilities in Lebanon; a yea ends US participation in an undeclared conflict.', 'https://www.congress.gov/bill/119th-congress/house-concurrent-resolution/108')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 1181 → gun_rights (primary), yea_supports
  VALUES (m_h_r_1181, 'gun_rights', 100, true, 'yea_supports', 'Protecting Privacy in Purchases Act bars payment-card networks from requiring or assigning a merchant category code that singles out firearms retailers; a yea blocks a gun-purchase tracking mechanism that gun-rights groups oppose.', 'https://www.congress.gov/bill/119th-congress/house-bill/1181')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.Amdt. 234 → climate_action (primary), yea_opposes
  VALUES (m_h_amdt_234, 'climate_action', 75, true, 'yea_opposes', 'Fine amendment to H.R. 8595 (FY2027 national security and State appropriations) would strike the $139,575,000 appropriation for the Global Environment Facility, the main US multilateral climate- and environment-finance channel; a yea defunds international climate finance. Weighted 75 because it is a single line item rather than a change in domestic climate policy.', 'https://www.congress.gov/amendment/119th-congress/house-amendment/234')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 9237 → veterans (primary), yea_supports
  VALUES (m_h_r_9237, 'veterans', 100, true, 'yea_supports', 'Take Care of America''s Veterans Act amends titles 10 and 38 to improve veterans'' benefits and VA administration; a yea expands veterans'' benefits.', 'https://www.congress.gov/bill/119th-congress/house-bill/9237')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.Amdt. 253 → gun_rights (primary), yea_supports
  VALUES (m_h_amdt_253, 'gun_rights', 100, true, 'yea_supports', 'Crank amendment to H.R. 8800 (FY2027 NDAA) establishes a presumption of approval for DoD servicemembers and civilian employees seeking their commander''s authorization to carry personal firearms on military installations; a yea expands lawful carry.', 'https://www.congress.gov/amendment/119th-congress/house-amendment/253')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.Amdt. 254 → lgbtq_rights (primary), yea_opposes
  VALUES (m_h_amdt_254, 'lgbtq_rights', 100, true, 'yea_opposes', 'Boebert amendment to H.R. 8800 (FY2027 NDAA) would codify Executive Order 14183, requiring all personnel to serve in accordance with their biological sex and thereby banning transgender service members; a yea removes an existing protection for transgender people.', 'https://www.congress.gov/amendment/119th-congress/house-amendment/254')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.Amdt. 255 → lgbtq_rights (primary), yea_opposes
  VALUES (m_h_amdt_255, 'lgbtq_rights', 100, true, 'yea_opposes', 'Mace amendment to H.R. 8800 (FY2027 NDAA) prohibits gender-related medical care under TRICARE and bars TRICARE from covering gender-related procedures and treatments; a yea withdraws transgender health coverage.', 'https://www.congress.gov/amendment/119th-congress/house-amendment/255')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.Amdt. 256 → lgbtq_rights (primary), yea_opposes
  VALUES (m_h_amdt_256, 'lgbtq_rights', 100, true, 'yea_opposes', 'Mace amendment to H.R. 8800 (FY2027 NDAA) prohibits male participation in female sports at Department of Defense Education Activity schools — a transgender sports-participation ban for military-dependent students; a yea restricts transgender participation.', 'https://www.congress.gov/amendment/119th-congress/house-amendment/256')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.Amdt. 257 → school_choice (primary), yea_supports
  VALUES (m_h_amdt_257, 'school_choice', 100, true, 'yea_supports', 'McDowell amendment to H.R. 8800 (FY2027 NDAA) would authorize the Secretary of Defense to establish a school choice pilot program for members of the Armed Forces; a yea creates a publicly funded school-choice program.', 'https://www.congress.gov/amendment/119th-congress/house-amendment/257')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.Amdt. 258 → religious_liberty (primary), yea_supports
  VALUES (m_h_amdt_258, 'religious_liberty', 85, true, 'yea_supports', 'Self amendment to H.R. 8800 (FY2027 NDAA) codifies protections and responsibilities for military chaplains and makes violations of those protections punishable under the Uniform Code of Military Justice; a yea strengthens statutory religious-exercise protection in the services.', 'https://www.congress.gov/amendment/119th-congress/house-amendment/258')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 8800 → strong_defense (primary), yea_supports
  VALUES (m_h_r_8800, 'strong_defense', 80, true, 'yea_supports', 'FY2027 National Defense Authorization Act — authorizes DoD military activities, military construction, DOE defense activities, and personnel strengths; a yea funds and authorizes the armed forces. Weighted 80 rather than 100 because this NDAA also carries unrelated social-policy riders (see H.Amdt. 254-256), so passage is not a pure defense-posture signal.', 'https://www.congress.gov/bill/119th-congress/house-bill/8800')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 7008 → stock_trading_ban (primary), yea_supports
  VALUES (m_h_r_7008, 'stock_trading_ban', 100, true, 'yea_supports', 'Stop Insider Trading Act amends chapter 131 of title 5 to bar Members of Congress, their spouses, and dependents from holding or trading covered individual stocks; a yea is a direct vote for the congressional stock-trading ban.', 'https://www.congress.gov/bill/119th-congress/house-bill/7008')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 7008 → gov_transparency, yea_supports
  VALUES (m_h_r_7008, 'gov_transparency', 60, false, 'yea_supports', 'Secondary: the bill''s enforcement machinery is disclosure-based — advance public notice of covered transactions and published divestiture certifications — so a yea also expands financial-disclosure transparency. Weighted below the primary because the bill is not a general transparency measure.', 'https://www.congress.gov/bill/119th-congress/house-bill/7008')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

